"""Browser-test server with native transcript lookup confined to fixture files."""
import os
import runpy
from pathlib import Path

from duckterm.runtimes.claude_code import ClaudeCodeRuntime


def fixture_transcript(self, *, cwd, session_id):
    # These files are generated by checkpoint-fixture.ts under the owned test
    # home and removed by teardown. Never consult the developer's conversations.
    if not isinstance(session_id, str) or not session_id.startswith("e2e-"):
        return None
    if any(char not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-" for char in session_id):
        return None
    path = Path(os.environ["CLAUDE_CONFIG_DIR"]) / "projects" / "checkpoint-fixtures" / (session_id + ".jsonl")
    return path if path.is_file() else None


ClaudeCodeRuntime.locate_transcript = fixture_transcript
runpy.run_module("duckterm.cli", run_name="__main__")
